import { createHmac } from 'node:crypto';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import worker from '../src/index';
import {
  resetSpanAttributes,
  spanAttributes
} from './mocks/cloudflare-workers';

const WEBHOOK_SECRET = '<REDACTED>';
const envelope = {
  id: 'evt_123',
  object: 'event',
  created_at: 1_750_287_018
} as const;

function signedWebhook(event: unknown): Request {
  const payload = JSON.stringify(event);
  const webhookID = 'wh_1';
  const timestamp = String(Math.floor(Date.now() / 1_000));
  const signature = createHmac('sha256', WEBHOOK_SECRET)
    .update(`${webhookID}.${timestamp}.${payload}`)
    .digest('base64');

  return new Request('https://executor.test/webhook', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'webhook-id': webhookID,
      'webhook-timestamp': timestamp,
      'webhook-signature': `v1,${signature}`
    },
    body: payload
  });
}

function executorFixture(overrides: Record<string, string> = {}) {
  const executor = {
    prewarm: vi.fn(async () => undefined),
    update: vi.fn(async () => undefined),
    destroy: vi.fn(async () => undefined)
  };
  const getByName = vi.fn(() => executor);
  const env = {
    EXECUTORS: { getByName },
    OPENAI_EXECUTOR_API_KEY: '<REDACTED>',
    EXECUTOR_CLIENT_SECRET: '<REDACTED>',
    EXECUTOR_KEEP_ALIVE_SECONDS: '30',
    EXECUTOR_PREWARM_ENABLED: 'true',
    EXECUTOR_SNAPSHOTS_ENABLED: 'true',
    OPENAI_API_KEY: '<REDACTED>',
    OPENAI_AGENT_ID: 'agent_1',
    OPENAI_WEBHOOK_SECRET: <REDACTED>
    ...overrides
  } as unknown as Env;
  return { env, executor, getByName };
}

function actionRequiredEvent() {
  return {
    ...envelope,
    type: 'agent.session.action_required',
    data: {
      id: 'sess_1',
      required_action: { type: 'environment_connection' }
    }
  };
}

function createdEvent() {
  return {
    ...envelope,
    type: 'agent.session.created',
    data: {
      id: 'sess_1',
      environment_id: 'env_1',
      environment_type: 'self_hosted',
      connect: { remote_url: 'https://api.openai.com/v1/agents/api' }
    }
  };
}

beforeEach(() => resetSpanAttributes());

describe('webhook routing', () => {
  it('records the caught error message on the failing span', async () => {
    const { env, executor } = executorFixture();
    executor.update.mockRejectedValueOnce(
      new Error('Container startup failed')
    );

    const response = await worker.fetch(
      signedWebhook(actionRequiredEvent()),
      env
    );

    expect(response.status).toBe(500);
    expect(spanAttributes).toContainEqual([
      'openai.webhook.type',
      'agent.session.action_required'
    ]);
    expect(spanAttributes).toContainEqual(['openai.webhook.data.id', 'sess_1']);
    expect(spanAttributes).toContainEqual(['error', true]);
    expect(spanAttributes).toContainEqual([
      'error.message',
      'Container startup failed'
    ]);
  });

  it('does not update an executor for a function-call action', async () => {
    const { env, executor } = executorFixture();

    const response = await worker.fetch(
      signedWebhook({
        ...envelope,
        type: 'agent.session.action_required',
        data: {
          id: 'sess_1',
          required_action: { type: 'function_call' }
        }
      }),
      env
    );

    expect(response.status).toBe(200);
    expect(executor.update).not.toHaveBeenCalled();
  });

  it('prewarms a self-hosted created event by default', async () => {
    const { env, executor } = executorFixture();

    const response = await worker.fetch(signedWebhook(createdEvent()), env);

    expect(response.status).toBe(200);
    expect(executor.prewarm).toHaveBeenCalledWith('sess_1');
    expect(executor.update).not.toHaveBeenCalled();
  });

  it('delegates created-event prewarming policy to the Durable Object', async () => {
    const { env, executor } = executorFixture();

    const response = await worker.fetch(signedWebhook(createdEvent()), env);

    expect(response.status).toBe(200);
    expect(executor.prewarm).toHaveBeenCalledWith('sess_1');
  });

  it.each(['agent.session.in_progress', 'agent.session.idle'] as const)(
    're-arms the deadline for %s',
    async (type) => {
      const { env, executor } = executorFixture();

      const response = await worker.fetch(
        signedWebhook({
          ...envelope,
          type,
          data: {
            id: 'sess_1',
            environment_id: 'env_1',
            environment_type: 'self_hosted'
          }
        }),
        env
      );

      expect(response.status).toBe(200);
      expect(executor.update).toHaveBeenCalledWith('sess_1');
    }
  );

  it('rejects a malformed supported event and traces the validation error', async () => {
    const { env, getByName } = executorFixture();

    const response = await worker.fetch(
      signedWebhook({
        ...envelope,
        type: 'agent.session.idle',
        data: { id: 'sess_1', environment_type: 'self_hosted' },
        created_at: 'invalid'
      }),
      env
    );

    expect(response.status).toBe(400);
    expect(getByName).not.toHaveBeenCalled();
    expect(spanAttributes).toContainEqual(['error', true]);
    expect(
      spanAttributes.some(
        ([name, value]) =>
          name === 'error.message' && String(value).includes('created_at')
      )
    ).toBe(true);
  });

  it('acknowledges an unknown future event without creating a stub', async () => {
    const { env, getByName } = executorFixture();

    const response = await worker.fetch(
      signedWebhook({
        ...envelope,
        type: 'agent.session.future_state',
        data: { id: 'sess_1', secret: '<REDACTED>' }
      }),
      env
    );

    expect(response.status).toBe(200);
    expect(getByName).not.toHaveBeenCalled();
    expect(spanAttributes.flat()).not.toContain('must-not-be-traced');
  });
});

import { SELF } from 'cloudflare:test';
import { env } from 'cloudflare:workers';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import worker from '../src/index';

const CLIENT_SECRET = '<REDACTED>';
const WEBHOOK_SECRET = '<REDACTED>';

async function signedWebhook(event: unknown, secret = <REDACTED> {
  const payload = JSON.stringify(event);
  const webhookID = 'wh_1';
  const timestamp = String(Math.floor(Date.now() / 1_000));
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  const signature = await crypto.subtle.sign(
    'HMAC',
    key,
    new TextEncoder().encode(`${webhookID}.${timestamp}.${payload}`)
  );

  return new Request('https://executor.test/webhook', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'webhook-id': webhookID,
      'webhook-timestamp': timestamp,
      'webhook-signature': `v1,${btoa(String.fromCharCode(...new Uint8Array(signature)))}`
    },
    body: payload
  });
}

const envelope = {
  id: 'evt_123',
  object: 'event',
  created_at: 1_750_287_018
} as const;

function actionRequiredEvent() {
  return {
    ...envelope,
    type: 'agent.session.action_required',
    data: {
      id: 'sess_1',
      required_action: { type: 'environment_connection' }
    }
  };
}

beforeEach(() => vi.unstubAllGlobals());

describe('Worker routes', () => {
  it('reports executor and webhook readiness', async () => {
    const response = await SELF.fetch('https://executor.test/health');

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toEqual({
      service: 'openai-agents-api-executor',
      configured: true,
      webhook_configured: true
    });
  });

  it('reports an invalid keep-alive deadline as unconfigured', async () => {
    const response = await worker.fetch(
      new Request('https://executor.test/health'),
      {
        ...env,
        EXECUTOR_KEEP_ALIVE_SECONDS: '604801'
      } as unknown as Env
    );

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toMatchObject({ configured: false });
  });

  it('returns a server error when required webhook settings are missing', async () => {
    const response = await worker.fetch(
      new Request('https://executor.test/webhook', { method: 'POST' }),
      { ...env, OPENAI_WEBHOOK_SECRET: '' }
    );

    expect(response.status).toBe(503);
  });

  it('rejects non-POST webhook requests', async () => {
    const response = await SELF.fetch('https://executor.test/webhook');

    expect(response.status).toBe(405);
  });

  it('does not expose a programmatic executor start endpoint', async () => {
    const response = await SELF.fetch(
      'https://executor.test/executors/sess_1',
      {
        method: 'POST'
      }
    );

    expect(response.status).toBe(404);
  });

  it('destroys an executor for manual cleanup', async () => {
    const response = await SELF.fetch(
      'https://executor.test/executors/sess_1',
      {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${CLIENT_SECRET}` }
      }
    );

    expect(response.status).toBe(204);
  });

  it('rejects an unauthorized manual cleanup request', async () => {
    const response = await SELF.fetch(
      'https://executor.test/executors/sess_1',
      {
        method: 'DELETE',
        headers: { Authorization: 'Bearer wrong-secret' }
      }
    );

    expect(response.status).toBe(401);
  });

  it('rejects an oversized webhook before signature verification', async () => {
    const response = await SELF.fetch('https://executor.test/webhook', {
      method: 'POST',
      body: 'x'.repeat(512 * 1024 + 1)
    });

    expect(response.status).toBe(413);
  });

  it('rejects an invalid webhook signature', async () => {
    const response = await SELF.fetch(
      await signedWebhook(actionRequiredEvent(), 'wrong-secret')
    );

    expect(response.status).toBe(400);
  });

  it('updates the session named by a signed webhook', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn(async () => new Response(null, { status: 404 }))
    );

    const response = await worker.fetch(
      await signedWebhook(actionRequiredEvent()),
      env
    );

    expect(response.status).toBe(200);
    expect(fetch).toHaveBeenCalledWith(
      'https://api.openai.com/v1/agents/sessions/sess_1',
      expect.objectContaining({
        headers: { Authorization: 'Bearer controller-key' }
      })
    );
  });

  it('prewarms from a signed created event', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn(async () => new Response(null, { status: 404 }))
    );

    const response = await worker.fetch(
      await signedWebhook({
        ...envelope,
        type: 'agent.session.created',
        data: {
          id: 'sess_1',
          environment_id: 'env_1',
          environment_type: 'self_hosted',
          connect: { remote_url: 'https://api.openai.test/v1' }
        }
      }),
      env
    );

    expect(response.status).toBe(200);
    expect(fetch).toHaveBeenCalledOnce();
  });

  it.each(['agent.session.in_progress', 'agent.session.idle'] as const)(
    'accepts a signed %s deadline event',
    async (type) => {
      vi.stubGlobal(
        'fetch',
        vi.fn(async () => new Response(null, { status: 404 }))
      );
      const response = await worker.fetch(
        await signedWebhook({
          ...envelope,
          type,
          data: {
            id: 'sess_1',
            environment_id: 'env_1',
            environment_type: 'self_hosted'
          }
        }),
        env
      );

      expect(response.status).toBe(200);
    }
  );

  it('ignores an unknown signed event type', async () => {
    const response = await SELF.fetch(
      await signedWebhook({
        ...envelope,
        type: 'agent.session.future_state',
        data: { id: 'sess_1' }
      })
    );

    expect(response.status).toBe(200);
  });
});

import type { AgentAPISDK } from '@openai/agents-api-preview';
import { describe, expect, it } from 'vitest';
import { runAgentTask } from '../src/agent-task.js';

async function* values<T>(items: T[]): AsyncGenerator<T> {
  yield* items;
}

describe('runAgentTask', () => {
  it('ignores idle emitted before the submitted turn starts', async () => {
    const stream = values([
      { type: 'session.idle' },
      {
        type: 'session.turn.completed',
        turn_id: 'turn_1',
        turn: { subagent_id: null }
      }
    ]);
    Object.assign(stream, { controller: { abort() {} } });
    const client = {
      beta: {
        agents: {
          sessions: {
            retrieve: async () => ({
              status: 'idle',
              required_actions: []
            }),
            events: {
              stream: async () => stream,
              create: async () => undefined
            },
            turns: { list: () => values([]) },
            items: {
              list: () =>
                values([
                  {
                    id: 'message_1',
                    type: 'message',
                    role: 'assistant',
                    status: 'completed',
                    phase: 'final_answer',
                    turn_id: 'turn_1',
                    content: [{ type: 'output_text', text: 'completed' }]
                  }
                ])
            }
          }
        }
      }
    } as unknown as AgentAPISDK;

    const output = await runAgentTask(client, 'sess_1', 'run', 30_000);

    expect(output).toBe('completed');
  });
});

import { describe, expect, it } from 'vitest';
import { createHandler } from '../src/index.js';
import type { SessionManager } from '../src/types.js';

function fixture() {
  const calls: Array<{ method: string; args: string[] }> = [];
  const manager: SessionManager = {
    async create(input) {
      calls.push({ method: 'create', args: [input] });
      return { sessionID: 'sess_1', output: 'created output' };
    },
    async run(sessionID, input) {
      calls.push({ method: 'run', args: [sessionID, input] });
      return { sessionID, output: 'follow-up output' };
    },
    async delete(sessionID) {
      calls.push({ method: 'delete', args: [sessionID] });
    }
  };
  return { app: createHandler(manager), calls };
}

describe('basic Agents API HTTP application', () => {
  it('reports health', async () => {
    const { app } = fixture();

    const response = await app(new Request('http://example.test/health'));

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toEqual({ ok: true });
  });

  it('creates a session and runs its first input', async () => {
    const { app, calls } = fixture();

    const response = await app(
      new Request('http://example.test/sessions', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ input: 'Create a file' })
      })
    );

    expect(response.status).toBe(201);
    await expect(response.json()).resolves.toEqual({
      session_id: 'sess_1',
      output: 'created output'
    });
    expect(calls).toEqual([{ method: 'create', args: ['Create a file'] }]);
  });

  it('runs follow-up input in an existing session', async () => {
    const { app, calls } = fixture();

    const response = await app(
      new Request('http://example.test/sessions/sess_1/input', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ input: 'Read the file' })
      })
    );

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toEqual({
      session_id: 'sess_1',
      output: 'follow-up output'
    });
    expect(calls).toEqual([
      { method: 'run', args: ['sess_1', 'Read the file'] }
    ]);
  });

  it('runs a complete demo and cleans up its session', async () => {
    const { app, calls } = fixture();

    const response = await app(
      new Request('http://example.test/demo', { method: 'POST' })
    );

    expect(response.status).toBe(200);
    await expect(response.json()).resolves.toEqual({
      session_id: 'sess_1',
      initial_output: 'created output',
      follow_up_output: 'follow-up output',
      cleaned_up: true
    });
    expect(calls[0]?.method).toBe('create');
    expect(calls[0]?.args[0]).toMatch(/write.*basic-demo\.txt/i);
    expect(calls[1]).toEqual({
      method: 'run',
      args: [
        'sess_1',
        'Read /workspace/basic-demo.txt and reply with its exact contents.'
      ]
    });
    expect(calls[2]).toEqual({ method: 'delete', args: ['sess_1'] });
  });

  it('cleans up a demo when its follow-up fails', async () => {
    const calls: string[] = [];
    const manager: SessionManager = {
      async create() {
        calls.push('create');
        return { sessionID: 'sess_1', output: 'created output' };
      },
      async run() {
        calls.push('run');
        throw new Error('follow-up failed');
      },
      async delete() {
        calls.push('delete');
      }
    };
    const app = createHandler(manager);

    const response = await app(
      new Request('http://example.test/demo', { method: 'POST' })
    );

    expect(response.status).toBe(500);
    await expect(response.json()).resolves.toEqual({
      error: 'follow-up failed'
    });
    expect(calls).toEqual(['create', 'run', 'delete']);
  });

  it('deletes a session and its executor', async () => {
    const { app, calls } = fixture();

    const response = await app(
      new Request('http://example.test/sessions/sess_1', {
        method: 'DELETE'
      })
    );

    expect(response.status).toBe(204);
    expect(calls).toEqual([{ method: 'delete', args: ['sess_1'] }]);
  });

  it('rejects missing input', async () => {
    const { app, calls } = fixture();

    const response = await app(
      new Request('http://example.test/sessions', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ input: '  ' })
      })
    );

    expect(response.status).toBe(400);
    await expect(response.json()).resolves.toEqual({
      error: 'input must be a non-empty string'
    });
    expect(calls).toEqual([]);
  });

  it('returns JSON for application errors', async () => {
    const manager: SessionManager = {
      async create() {
        throw new Error('session failed');
      },
      async run() {
        throw new Error('session failed');
      },
      async delete() {
        throw new Error('session failed');
      }
    };
    const app = createHandler(manager);

    const response = await app(
      new Request('http://example.test/sessions', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ input: 'Run' })
      })
    );

    expect(response.status).toBe(500);
    await expect(response.json()).resolves.toEqual({ error: 'session failed' });
  });
});

