export class ArtifactSandbox extends DurableObject<Env> {
  readonly #container: Container;
  readonly #files: Files;
  readonly #mounts: S3Mount;

  constructor(ctx: ArtifactSandboxState, env: Env) {
    super(ctx, env);
    this.#container = requireContainer(ctx);
    this.#files = new Files(this.#container);
    this.#mounts = new S3Mount(this.#container, ctx.exports.S3Gateway);
    // Each Durable Object instance must set its own timeout; it is not inherited.
    if (this.#container.running) {
      void ctx.blockConcurrencyWhile(() =>
        this.#container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS),
      );
    }
  }

  async writeInput(source: ReadableStream<Uint8Array>, sandboxName: string): Promise<void> {
    await this.#ensureArtifacts(sandboxName);
    await this.#files.writeFile(INPUT_PATH, source);
  }

  async computeDigest(sandboxName: string): Promise<Response> {
    await this.#ensureArtifacts(sandboxName);
    const process = await this.#container.exec(
      ["/bin/sh", "-c", "sha256sum /artifacts/input.txt > /artifacts/output.sha256"],
      { cwd: MOUNT_PATH },
    );
    const output = await process.output();
    if (output.exitCode !== 0) {
      throw new Error(
        `artifact processing exited with ${output.exitCode}: ${new TextDecoder().decode(output.stderr)}`,
      );
    }
    return this.#files.readFile(DIGEST_PATH);
  }

  async readDigest(sandboxName: string): Promise<Response> {
    await this.#ensureArtifacts(sandboxName);
    return this.#files.readFile(DIGEST_PATH);
  }

  async inspectMount(): Promise<S3MountInspection> {
    if (!this.#container.running) {
      return { mountPath: MOUNT_PATH, attachment: { status: "absent" } };
    }
    return this.#mounts.inspect(MOUNT_PATH);
  }

  async unmountArtifacts(): Promise<void> {
    if (!this.#container.running) return;
    await this.#mounts.unmount(MOUNT_PATH);
  }

  async resetExecution(): Promise<void> {
    if (!this.#container.running) return;
    await this.#mounts.unmount(MOUNT_PATH);
    await this.#container.destroy();
  }

  async #ensureArtifacts(sandboxName: string): Promise<void> {
    await this.#ensureExecution(sandboxName);
    await this.#mounts.mount(this.#mountRequest(sandboxName));
  }

  async #ensureExecution(sandboxName: string): Promise<void> {
    if (this.#container.running) return;
    this.#container.start({
      image: this.#container.images.sandbox,
      instance: "lite",
      enableInternet: false,
      labels: { example: "artifact-workspace", sandbox: sandboxName },
    });
    await this.#container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS);
  }

  #mountRequest(sandboxName: string): S3MountRequest {
    return {
      mountPath: MOUNT_PATH,
      source: {
        type: "s3",
        endpoint: this.env.S3_ENDPOINT,
        bucket: this.env.S3_BUCKET,
        region: this.env.S3_REGION,
        credentials: {
          type: "static",
          accessKeyId: this.env.S3_ACCESS_KEY_ID,
          secretAccessKey: <REDACTED>
        },
      },
      keyPrefix: `sandboxes/${sandboxName}`,
      access: "read-write",
    };
  }
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    const match = /^\/sandboxes\/([^/]+)\/(input|digest|mount|execution)$/.exec(url.pathname);
    if (match === null) return new Response("Not found", { status: 404 });

    const sandboxName = match[1];
    const resource = match[2];
    if (!SANDBOX_NAME_PATTERN.test(sandboxName)) {
      return new Response(
        "sandbox name must contain 1-63 lowercase letters, digits, or hyphens and start with a letter or digit",
        { status: 400 },
      );
    }

    const sandbox = env.SANDBOX.getByName(sandboxName);
    try {
      if (resource === "input" && request.method === "PUT") {
        if (request.body === null) return new Response("Request body is required", { status: 400 });
        await sandbox.writeInput(request.body, sandboxName);
        return new Response(null, { status: 204 });
      }
      if (resource === "digest" && request.method === "POST") {
        return await sandbox.computeDigest(sandboxName);
      }
      if (resource === "digest" && request.method === "GET") {
        return await sandbox.readDigest(sandboxName);
      }
      if (resource === "mount" && request.method === "GET") {
        return Response.json(await sandbox.inspectMount());
      }
      if (resource === "mount" && request.method === "DELETE") {
        await sandbox.unmountArtifacts();
        return new Response(null, { status: 204 });
      }
      if (resource === "execution" && request.method === "DELETE") {
        await sandbox.resetExecution();
        return new Response(null, { status: 204 });
      }
      return new Response("Method not allowed", { status: 405 });
    } catch (cause) {
      console.error({
        event: "sandbox.request.failed",
        sandboxName,
        resource,
        error: describeError(cause),
      });
      return errorResponse(cause);
    }
  },
} satisfies ExportedHandler<Env>;

// Structured logs drop an Error's message and stack because they are not enumerable.
function describeError(cause: unknown): string {
  return cause instanceof Error && cause.stack !== undefined ? cause.stack : String(cause);
}

function requireContainer(ctx: DurableObjectState): Container {
  const container = ctx.container;
  if (container === undefined) throw new Error("Container attachment is unavailable");
  return container;
}

function errorResponse(cause: unknown): Response {
  if (SandboxFileError.is(cause)) {
    if (cause.code === "ENOENT") return new Response("Artifact not found", { status: 404 });
    if (cause.code === "EACCES" || cause.code === "EPERM") {
      return new Response("Artifact permission denied", { status: 403 });
    }
    return new Response("Artifact file operation failed", { status: 500 });
  }
  if (SandboxS3MountError.is(cause)) {
    const conflict = cause.code === "S3_MOUNT_BUSY" || cause.code === "S3_MOUNT_CONFLICT";
    return new Response("Artifact mount operation failed", { status: conflict ? 409 : 500 });
  }
  if (SandboxProtocolError.is(cause)) {
    return new Response("Sandbox protocol failed", { status: 500 });
  }
  return new Response("Artifact processing failed", { status: 500 });
}

import {
  DirectoryBackup,
  type DirectoryBackupGatewayBinding,
  type DirectoryBackupRecord,
  SandboxBackupError,
  SandboxFileError,
} from "@cloudflare/sandbox";
import { DurableObject } from "cloudflare:workers";
import { z } from "zod";

export { DirectoryBackupGateway } from "@cloudflare/sandbox";

const SANDBOX_NAME_PATTERN = /^[a-z0-9][a-z0-9-]{0,62}$/;
const BACKUP_ID_PATTERN = /^[0-9a-f-]{36}$/;
const INACTIVITY_TIMEOUT_MS = 10 * 60 * 1_000;
const OPERATION_TIMEOUT_MS = 10 * 60 * 1_000;
const DEFAULT_TTL_SECONDS = 3 * 24 * 60 * 60;
const BACKUP_KEY_PREFIX = "backup:";

// Restoring replaces the directory, so backups are limited to directories that hold work.
const BackupDirectory = z
  .string()
  .regex(
    /^\/(workspace|home|tmp|var\/tmp|app)(\/[^/\0]+)*$/,
    "use a directory under /workspace, /home, /tmp, /var/tmp, or /app",
  )
  .refine((path) => !path.split("/").some((part) => part === "." || part === ".."), {
    message: "the directory cannot contain . or .. segments",
  });

const CreateBackupRequest = z.object({
  dir: BackupDirectory,
  name: z.string().max(200).optional(),
  // gitignore patterns, relative to dir. "node_modules/" matches at any depth; "/build" only
  // at the top.
  exclude: z.array(z.string().min(1).max(200)).max(100).optional(),
  gitignore: z.boolean().optional(),
  ttlSeconds: z
    .int()
    .min(60)
    .max(365 * 24 * 60 * 60)
    .default(DEFAULT_TTL_SECONDS),
});
const RestoreRequest = z.object({ dir: BackupDirectory.optional() });
const CommandRequest = z.object({ argv: z.array(z.string()).min(1) });

interface Env {
  SANDBOX: DurableObjectNamespace<BackupSandbox>;
  BACKUPS: R2Bucket;
}

interface BackupSandboxState extends DurableObjectState {
  readonly exports: Cloudflare.Exports & {
    readonly DirectoryBackupGateway: DirectoryBackupGatewayBinding;
  };
}

// The record DirectoryBackup returns, with the expiry this example adds.
interface StoredBackup {
  backup: DirectoryBackupRecord;
  createdAt: string;
  expiresAt: string;
}

export class BackupSandbox extends DurableObject<Env> {
  readonly #container: Container;
  readonly #backups: DirectoryBackup;

  constructor(ctx: BackupSandboxState, env: Env) {
    super(ctx, env);
    this.#container = requireContainer(ctx);
    // Each Durable Object keeps its own records, so every sandbox can share one prefix.
    this.#backups = new DirectoryBackup(this.#container, ctx.exports.DirectoryBackupGateway, {
      binding: "BACKUPS",
      prefix: "backups/",
    });
    // Each Durable Object instance must set its own timeout; it is not inherited.
    if (this.#container.running) {
      void ctx.blockConcurrencyWhile(() =>
        this.#container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS),
      );
    }
  }

  async createBackup(
    sandboxName: string,
    request: z.infer<typeof CreateBackupRequest>,
  ): Promise<StoredBackup> {
    await this.#ensureExecution(sandboxName);
    const { ttlSeconds, ...options } = request;
    const backup = await withTimeout((signal) => this.#backups.backup({ ...options, signal }));
    const createdAt = new Date();
    const stored: StoredBackup = {
      backup,
      createdAt: createdAt.toISOString(),
      expiresAt: new Date(createdAt.getTime() + ttlSeconds * 1_000).toISOString(),
    };
    this.ctx.storage.kv.put(BACKUP_KEY_PREFIX + backup.id, stored);
    await this.#scheduleExpiry(new Date(stored.expiresAt));
    return stored;
  }

  listBackups(): StoredBackup[] {
    const entries = this.ctx.storage.kv.list<StoredBackup>({ prefix: BACKUP_KEY_PREFIX });
    return Array.from(entries, ([, stored]) => stored);
  }

  // Replaces the directory, in the running Container or a new one.
  async restoreBackup(sandboxName: string, id: string, dir?: string): Promise<string | null> {
    const stored = this.#find(id);
    if (stored === undefined) return null;
    await this.#ensureExecution(sandboxName);
    await withTimeout((signal) => this.#backups.restore(stored.backup, { dir, signal }));
    return dir ?? stored.backup.dir;
  }

  async deleteBackup(id: string): Promise<boolean> {
    const stored = this.#find(id);
    if (stored === undefined) return false;
    await this.#backups.delete(stored.backup);
    this.ctx.storage.kv.delete(BACKUP_KEY_PREFIX + id);
    return true;
  }

  async run(
    sandboxName: string,
    argv: string[],
  ): Promise<{ exitCode: number; stdout: string; stderr: string }> {
    await this.#ensureExecution(sandboxName);
    const process = await withTimeout((signal) =>
      this.#container.exec(argv, { cwd: "/workspace", signal }).then((child) => child.output()),
    );
    const decoder = new TextDecoder();
    return {
      exitCode: process.exitCode,
      stdout: decoder.decode(process.stdout),
      stderr: decoder.decode(process.stderr),
    };
  }

  async resetExecution(): Promise<void> {
    if (this.#container.running) await this.#container.destroy();
  }

  // Deletes expired backups, then waits for the next one to expire.
  override async alarm(): Promise<void> {
    const now = Date.now();
    let next: number | undefined;
    for (const stored of this.listBackups()) {
      const expiresAt = Date.parse(stored.expiresAt);
      if (expiresAt <= now) {
        await this.deleteBackup(stored.backup.id);
        console.log({ event: "backup.expired", id: stored.backup.id });
      } else if (next === undefined || expiresAt < next) {
        next = expiresAt;
      }
    }
    if (next !== undefined) await this.ctx.storage.setAlarm(next);
  }

  #find(id: string): StoredBackup | undefined {
    return this.ctx.storage.kv.get<StoredBackup>(BACKUP_KEY_PREFIX + id);
  }

  async #scheduleExpiry(expiresAt: Date): Promise<void> {
    const current = await this.ctx.storage.getAlarm();
    if (current === null || expiresAt.getTime() < current) {
      await this.ctx.storage.setAlarm(expiresAt);
    }
  }

  async #ensureExecution(sandboxName: string): Promise<void> {
    if (this.#container.running) return;
    this.#container.start({
      image: this.#container.images.sandbox,
      instance: "lite",
      enableInternet: false,
      labels: { example: "backup-workspace", sandbox: sandboxName },
    });
    await this.#container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS);
  }
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    const match =
      /^\/sandboxes\/([^/]+)\/(backups|commands|execution)(?:\/([^/]+))?(?:\/(restore))?$/.exec(
        url.pathname,
      );
    if (match === null) return new Response("Not found", { status: 404 });
    const [, sandboxName, resource, id, action] = match;
    if (!SANDBOX_NAME_PATTERN.test(sandboxName)) {
      return new Response(
        "sandbox name must contain 1-63 lowercase letters, digits, or hyphens and start with a letter or digit",
        { status: 400 },
      );
    }
    if (id !== undefined && (resource !== "backups" || !BACKUP_ID_PATTERN.test(id))) {
      return new Response("Not found", { status: 404 });
    }

    const sandbox = env.SANDBOX.getByName(sandboxName);
    try {
      if (resource === "backups" && id === undefined && request.method === "POST") {
        const backup = CreateBackupRequest.parse(await request.json());
        return Response.json(await sandbox.createBackup(sandboxName, backup), { status: 201 });
      }
      if (resource === "backups" && id === undefined && request.method === "GET") {
        return Response.json(await sandbox.listBackups());
      }
      if (
        resource === "backups" &&
        id !== undefined &&
        action === "restore" &&
        request.method === "POST"
      ) {
        const body = request.headers.get("Content-Length") === "0" ? {} : await request.json();
        const { dir } = RestoreRequest.parse(body);
        const restored = await sandbox.restoreBackup(sandboxName, id, dir);
        if (restored === null) return new Response("Backup not found", { status: 404 });
        return Response.json({ id, dir: restored });
      }
      if (
        resource === "backups" &&
        id !== undefined &&
        action === undefined &&
        request.method === "DELETE"
      ) {
        return (await sandbox.deleteBackup(id))
          ? new Response(null, { status: 204 })
          : new Response("Backup not found", { status: 404 });
      }
      if (resource === "commands" && id === undefined && request.method === "POST") {
        const { argv } = CommandRequest.parse(await request.json());
        return Response.json(await sandbox.run(sandboxName, argv));
      }
      if (resource === "execution" && id === undefined && request.method === "DELETE") {
        await sandbox.resetExecution();
        return new Response(null, { status: 204 });
      }
      return new Response("Method not allowed", { status: 405 });
    } catch (cause) {
      if (cause instanceof z.ZodError) return new Response(z.prettifyError(cause), { status: 400 });
      if (cause instanceof SyntaxError) {
        return new Response("Request body must be JSON", { status: 400 });
      }
      // Errors keep their recognizers across Durable Object RPC.
      if (SandboxFileError.is(cause)) {
        return Response.json({ code: cause.code, path: cause.path }, { status: 422 });
      }
      if (SandboxBackupError.is(cause)) {
        const status = cause.code === "BACKUP_NOT_FOUND" ? 404 : 502;
        return Response.json({ code: cause.code, detail: cause.detail }, { status });
      }
      console.error({
        event: "sandbox.request.failed",
        sandboxName,
        resource,
        error: describeError(cause),
      });
      return new Response("Sandbox request failed", { status: 500 });
    }
  },
} satisfies ExportedHandler<Env>;

// Not AbortSignal.timeout(): it stays armed after the operation ends, and exec() signals a process
// that has already exited, which logs a runtime error. Clear the timer instead.
async function withTimeout<T>(operation: (signal: AbortSignal) => Promise<T>): Promise<T> {
  const abort = new AbortController();
  const timer = setTimeout(() => abort.abort(), OPERATION_TIMEOUT_MS);
  try {
    return await operation(abort.signal);
  } finally {
    clearTimeout(timer);
  }
}

function requireContainer(ctx: DurableObjectState): Container {
  const container = ctx.container;
  if (container === undefined) throw new Error("Container attachment is unavailable");
  return container;
}

// Structured logs drop an Error's message and stack because they are not enumerable.
function describeError(cause: unknown): string {
  return cause instanceof Error && cause.stack !== undefined ? cause.stack : String(cause);
}

import { Files, SandboxFileError, SandboxProtocolError } from "@cloudflare/sandbox";
import { DurableObject } from "cloudflare:workers";

const ACTIVE_CHECKPOINT_KEY = "active-container-checkpoint";
const WORKSPACE_FILE = "/workspace/message.txt";
const SANDBOX_NAME_PATTERN = /^[a-z0-9][a-z0-9-]{0,62}$/;
const INACTIVITY_TIMEOUT_MS = 10 * 60 * 1_000;

interface ActiveCheckpoint {
  id: string;
}

interface CheckpointResult {
  id: string;
  name: string | null;
  size: number;
}

interface Env {
  SANDBOX: DurableObjectNamespace<CheckpointSandbox>;
}

export class CheckpointSandbox extends DurableObject<Env> {
  readonly files: Files;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    const container = this.requireContainer();
    this.files = new Files(container);
    // Each Durable Object instance must set its own timeout; it is not inherited.
    if (container.running) {
      void ctx.blockConcurrencyWhile(() => container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS));
    }
  }

  async writeWorkspace(content: ReadableStream<Uint8Array>, sandboxName: string): Promise<void> {
    await this.ensureExecution(sandboxName);
    await this.files.writeFile(WORKSPACE_FILE, content);
  }

  async readWorkspace(sandboxName: string): Promise<Response> {
    await this.ensureExecution(sandboxName);
    return this.files.readFile(WORKSPACE_FILE);
  }

  async checkpoint(sandboxName: string): Promise<CheckpointResult> {
    const container = await this.ensureExecution(sandboxName);
    const snapshot = await container.snapshotContainer({});
    await this.ctx.storage.put<ActiveCheckpoint>(ACTIVE_CHECKPOINT_KEY, { id: snapshot.id });
    await container.destroy();
    return { id: snapshot.id, size: snapshot.size, name: snapshot.name ?? null };
  }

  async restoreFrom(snapshotID: string): Promise<void> {
    const container = this.requireContainer();
    if (container.running) {
      throw new Error("Reset the current execution before selecting another checkpoint");
    }
    await this.ctx.storage.put<ActiveCheckpoint>(ACTIVE_CHECKPOINT_KEY, { id: snapshotID });
  }

  async resetWorkspace(): Promise<void> {
    const container = this.requireContainer();
    if (container.running) await container.destroy();
    await this.ctx.storage.delete(ACTIVE_CHECKPOINT_KEY);
  }

  private async ensureExecution(sandboxName: string): Promise<Container> {
    const container = this.requireContainer();
    if (container.running) return container;

    const checkpoint = await this.ctx.storage.get<ActiveCheckpoint>(ACTIVE_CHECKPOINT_KEY);
    const commonOptions = {
      instance: "lite" as const,
      enableInternet: false,
      labels: { example: "checkpoint-workspace", sandbox: sandboxName },
    };
    if (checkpoint === undefined) {
      container.start({ image: container.images.sandbox, ...commonOptions });
    } else {
      container.start({ containerSnapshot: { id: checkpoint.id }, ...commonOptions });
    }
    // Without it, the Container can stop between writing the workspace and checkpointing it.
    await container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS);
    return container;
  }

  private requireContainer(): Container {
    const container = this.ctx.container;
    if (container === undefined) {
      throw new Error("Container attachment is unavailable");
    }
    return container;
  }
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    const match = /^\/sandboxes\/([^/]+)\/(workspace|checkpoint|restore)$/.exec(url.pathname);
    if (match === null) return new Response("Not found", { status: 404 });

    const sandboxName = match[1];
    const resource = match[2];
    if (!SANDBOX_NAME_PATTERN.test(sandboxName)) {
      return new Response(
        "sandbox name must contain 1-63 lowercase letters, digits, or hyphens and start with a letter or digit",
        { status: 400 },
      );
    }

    const sandbox = env.SANDBOX.getByName(sandboxName);
    try {
      if (resource === "workspace" && request.method === "GET") {
        return await sandbox.readWorkspace(sandboxName);
      }
      if (resource === "workspace" && request.method === "PUT") {
        if (request.body === null) {
          return new Response("Request body is required", { status: 400 });
        }
        await sandbox.writeWorkspace(request.body, sandboxName);
        return new Response(null, { status: 204 });
      }
      if (resource === "checkpoint" && request.method === "POST") {
        return Response.json(await sandbox.checkpoint(sandboxName));
      }
      if (resource === "restore" && request.method === "POST") {
        const snapshotID = url.searchParams.get("snapshot");
        if (snapshotID === null || snapshotID.length === 0 || snapshotID.length > 256) {
          return new Response("snapshot must contain a non-empty snapshot ID", { status: 400 });
        }
        await sandbox.restoreFrom(snapshotID);
        return new Response(null, { status: 204 });
      }
      if (resource === "workspace" && request.method === "DELETE") {
        await sandbox.resetWorkspace();
        return new Response(null, { status: 204 });
      }
      return new Response("Method not allowed", { status: 405 });
    } catch (cause) {
      console.error({
        event: "sandbox.request.failed",
        sandboxName,
        resource,
        error: describeError(cause),
      });
      return errorResponse(cause);
    }
  },
} satisfies ExportedHandler<Env>;

// Structured logs drop an Error's message and stack because they are not enumerable.
function describeError(cause: unknown): string {
  return cause instanceof Error && cause.stack !== undefined ? cause.stack : String(cause);
}

function errorResponse(cause: unknown): Response {
  if (SandboxFileError.is(cause)) {
    const missing = cause.code === "ENOENT";
    return new Response(missing ? "Workspace state not found" : "Workspace file operation failed", {
      status: missing ? 404 : 500,
    });
  }
  if (SandboxProtocolError.is(cause)) {
    return new Response("Sandbox file protocol failed", { status: 500 });
  }
  return new Response("Sandbox checkpoint operation failed", { status: 500 });
}

import { Files, SandboxFileError, SandboxProtocolError } from "@cloudflare/sandbox";
import { DurableObject } from "cloudflare:workers";
import { z } from "zod";

const SANDBOX_NAME_PATTERN = /^[a-z0-9][a-z0-9-]{0,62}$/;
const WORKSPACE_DIRECTORY = "/workspace";
const INACTIVITY_TIMEOUT_MS = 10 * 60 * 1_000;

const ExecRequest = z.object({ argv: z.array(z.string()).min(1) });

interface Env {
  SANDBOX: DurableObjectNamespace<Sandbox>;
}

interface CommandResult {
  exitCode: number;
  stdout: string;
  stderr: string;
}

export class Sandbox extends DurableObject<Env> {
  readonly files: Files;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    const container = this.requireContainer();
    this.files = new Files(container);
    // Each Durable Object instance must set its own timeout; it is not inherited.
    if (container.running) {
      void ctx.blockConcurrencyWhile(() => container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS));
    }
  }

  async writeFile(path: string, contents: ReadableStream<Uint8Array>): Promise<void> {
    await this.ensureRunning();
    await this.files.writeFile(path, contents);
  }

  async readFile(path: string): Promise<Response> {
    await this.ensureRunning();
    return this.files.readFile(path);
  }

  async exec(argv: string[]): Promise<CommandResult> {
    const container = await this.ensureRunning();
    const process = await container.exec(argv, { cwd: WORKSPACE_DIRECTORY });
    const output = await process.output();
    const decoder = new TextDecoder();
    return {
      exitCode: output.exitCode,
      stdout: decoder.decode(output.stdout),
      stderr: decoder.decode(output.stderr),
    };
  }

  async destroy(): Promise<void> {
    const container = this.requireContainer();
    if (container.running) await container.destroy();
  }

  private async ensureRunning(): Promise<Container> {
    const container = this.requireContainer();
    if (!container.running) {
      container.start({
        image: container.images.sandbox,
        instance: "lite",
        enableInternet: false,
      });
      await container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS);
    }
    return container;
  }

  private requireContainer(): Container {
    const container = this.ctx.container;
    if (container === undefined) {
      throw new Error("Container attachment is unavailable");
    }
    return container;
  }
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    const match = /^\/sandboxes\/([^/]+)(\/exec|\/files(\/.+))?$/.exec(url.pathname);
    if (match === null) return new Response("Not found", { status: 404 });

    const sandboxName = match[1];
    if (!SANDBOX_NAME_PATTERN.test(sandboxName)) {
      return new Response(
        "sandbox name must contain 1-63 lowercase letters, digits, or hyphens and start with a letter or digit",
        { status: 400 },
      );
    }

    const sandbox = env.SANDBOX.getByName(sandboxName);
    const filePath = match[3] === undefined ? undefined : workspacePath(match[3]);
    if (match[3] !== undefined && filePath === undefined) {
      return new Response("Invalid file path", { status: 400 });
    }
    try {
      if (match[2] === "/exec" && request.method === "POST") {
        const { argv } = ExecRequest.parse(await request.json());
        return Response.json(await sandbox.exec(argv));
      }
      if (filePath !== undefined && request.method === "PUT") {
        if (request.body === null) {
          return new Response("Request body is required", { status: 400 });
        }
        await sandbox.writeFile(filePath, request.body);
        return new Response(null, { status: 204 });
      }
      if (filePath !== undefined && request.method === "GET") {
        return await sandbox.readFile(filePath);
      }
      if (match[2] === undefined && request.method === "DELETE") {
        await sandbox.destroy();
        return new Response(null, { status: 204 });
      }
      return new Response("Method not allowed", { status: 405 });
    } catch (cause) {
      if (cause instanceof SyntaxError || cause instanceof z.ZodError) {
        return new Response('Body must be JSON such as {"argv": ["ls", "-la"]}', { status: 400 });
      }
      console.error({
        event: "sandbox.request.failed",
        sandboxName,
        path: url.pathname,
        error: describeError(cause),
      });
      return errorResponse(cause);
    }
  },
} satisfies ExportedHandler<Env>;

// Files follows Linux path rules and enforces no policy, so the Worker keeps paths in /workspace.
function workspacePath(routePath: string): string | undefined {
  let decoded: string;
  try {
    decoded = decodeURIComponent(routePath);
  } catch {
    return undefined;
  }
  const segments = decoded.split("/").slice(1);
  if (segments.some((segment) => segment === "" || segment === "." || segment === "..")) {
    return undefined;
  }
  return `${WORKSPACE_DIRECTORY}/${segments.join("/")}`;
}

// Structured logs drop an Error's message and stack because they are not enumerable.
function describeError(cause: unknown): string {
  return cause instanceof Error && cause.stack !== undefined ? cause.stack : String(cause);
}

function errorResponse(cause: unknown): Response {
  if (SandboxFileError.is(cause)) {
    if (cause.code === "ENOENT") return new Response("No such file or directory", { status: 404 });
    if (cause.code === "EACCES" || cause.code === "EPERM") {
      return new Response("Permission denied", { status: 403 });
    }
    return new Response("File operation failed", { status: 500 });
  }
  if (SandboxProtocolError.is(cause)) {
    return new Response("Sandbox file protocol failed", { status: 500 });
  }
  return new Response("Sandbox request failed", { status: 500 });
}

import { DurableObject, WorkerEntrypoint } from "cloudflare:workers";
import { z } from "zod";

import { decide, type HandlerName, OutboundRules } from "./rules.js";

const SANDBOX_NAME_PATTERN = /^[a-z0-9][a-z0-9-]{0,62}$/;
const INACTIVITY_TIMEOUT_MS = 10 * 60 * 1_000;
const RULES_KEY = "outbound-rules";
const COMMAND_TIMEOUT_MS = 60_000;
const CA_PATH = "/etc/cloudflare/certs/cloudflare-containers-ca.crt";
// HTTPS interception re-signs traffic with a Containers CA. exec() does not inherit the
// environment from start(), so pass this on every command that makes HTTPS requests.
const TRUST_ENV = { CURL_CA_BUNDLE: CA_PATH, SSL_CERT_FILE: CA_PATH, NODE_EXTRA_CA_CERTS: CA_PATH };

const CommandRequest = z.object({ argv: z.array(z.string()).min(1) });

interface Env {
  SANDBOX: DurableObjectNamespace<OutboundSandbox>;
  // Optional. The bearer-token handler sends it to the hosts it handles.
  UPSTREAM_TOKEN?: string;
}

interface OutboundProps {
  sandboxName: string;
}

interface OutboundSandboxState extends DurableObjectState {
  readonly exports: Cloudflare.Exports & {
    readonly Outbound: LoopbackForExport<typeof Outbound>;
  };
}

// Every HTTP request on port 80 and HTTPS request on port 443 reaches this entrypoint. It reads the
// current rules on each request, so a rule change applies to the next request.
export class Outbound extends WorkerEntrypoint<Env, OutboundProps> {
  override async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const rules = await this.env.SANDBOX.getByName(this.ctx.props.sandboxName).outboundRules();
    const decision = decide(rules, url.hostname);
    if (decision.action === "deny") return new Response(`${decision.reason}\n`, { status: 403 });
    if (decision.action === "fetch") return fetch(request);
    return this.#handle(decision.handler, request, url);
  }

  #handle(handler: HandlerName, request: Request, url: URL): Promise<Response> | Response {
    if (handler === "audit") {
      console.log({ event: "outbound.audit", method: request.method, url: request.url });
      return fetch(request);
    }
    // Credentials stay in the Worker. The Container never sees the token. The Worker fetches with
    // the guest's scheme, so a token added to plain HTTP would cross the Internet unencrypted.
    if (url.protocol !== "https:") {
      return new Response("bearer-token sends its token only over HTTPS\n", { status: 403 });
    }
    if (this.env.UPSTREAM_TOKEN =<REDACTED> undefined) {
      return new Response("UPSTREAM_TOKEN is not set\n", { status: 500 });
    }
    const headers = new Headers(request.headers);
    headers.set("Authorization", `Bearer ${this.env.UPSTREAM_TOKEN}`);
    return fetch(new Request(request, { headers }));
  }
}

export class OutboundSandbox extends DurableObject<Env> {
  readonly #container: Container;
  readonly #exports: OutboundSandboxState["exports"];

  constructor(ctx: OutboundSandboxState, env: Env) {
    super(ctx, env);
    this.#container = requireContainer(ctx);
    this.#exports = ctx.exports;
    // Each Durable Object instance must set its own timeout; it is not inherited.
    if (this.#container.running) {
      void ctx.blockConcurrencyWhile(() =>
        this.#container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS),
      );
    }
  }

  // Rules live in Durable Object storage, so they outlast the Container and apply to the next one.
  outboundRules(): OutboundRules {
    return OutboundRules.parse(this.ctx.storage.kv.get(RULES_KEY) ?? {});
  }

  setOutboundRules(rules: OutboundRules): OutboundRules {
    this.ctx.storage.kv.put(RULES_KEY, rules);
    return rules;
  }

  async run(
    sandboxName: string,
    argv: string[],
  ): Promise<{ exitCode: number; stdout: string; stderr: string }> {
    await this.#ensureExecution(sandboxName);
    // Not AbortSignal.timeout(): it stays armed after the command exits, and signalling an
    // exited process logs an internal error. Clear the timer instead.
    const abort = new AbortController();
    const timer = setTimeout(() => abort.abort(), COMMAND_TIMEOUT_MS);
    try {
      const process = await this.#container.exec(argv, {
        cwd: "/workspace",
        env: TRUST_ENV,
        signal: abort.signal,
      });
      const output = await process.output();
      const decoder = new TextDecoder();
      return {
        exitCode: output.exitCode,
        stdout: decoder.decode(output.stdout),
        stderr: decoder.decode(output.stderr),
      };
    } finally {
      clearTimeout(timer);
    }
  }

  async resetExecution(): Promise<void> {
    if (this.#container.running) await this.#container.destroy();
  }

  async #ensureExecution(sandboxName: string): Promise<void> {
    if (this.#container.running) return;
    this.#container.start({
      image: this.#container.images.sandbox,
      instance: "lite",
      // Only HTTP on port 80 and HTTPS on port 443 leave the Container, through the intercepts
      // below. Connections to other ports time out. With enableInternet: true, they would go out
      // directly and skip the rules.
      enableInternet: false,
      labels: { example: "outbound-workspace", sandbox: sandboxName },
    });
    // Intercepts last for this Container run. The rules can change without installing them again.
    const outbound = this.#exports.Outbound({ props: { sandboxName } });
    await this.#container.interceptAllOutboundHttp(outbound);
    await this.#container.interceptOutboundHttps("*", outbound);
    await this.#container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS);
  }
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    const match = /^\/sandboxes\/([^/]+)\/(outbound-rules|commands|execution)$/.exec(url.pathname);
    if (match === null) return new Response("Not found", { status: 404 });
    const [, sandboxName, resource] = match;
    if (!SANDBOX_NAME_PATTERN.test(sandboxName)) {
      return new Response(
        "sandbox name must contain 1-63 lowercase letters, digits, or hyphens and start with a letter or digit",
        { status: 400 },
      );
    }

    const sandbox = env.SANDBOX.getByName(sandboxName);
    try {
      if (resource === "outbound-rules" && request.method === "GET") {
        return Response.json(await sandbox.outboundRules());
      }
      if (resource === "outbound-rules" && request.method === "PUT") {
        const rules = await parseBody(request, OutboundRules);
        return Response.json(await sandbox.setOutboundRules(rules));
      }
      if (resource === "commands" && request.method === "POST") {
        const { argv } = await parseBody(request, CommandRequest);
        return Response.json(await sandbox.run(sandboxName, argv));
      }
      if (resource === "execution" && request.method === "DELETE") {
        await sandbox.resetExecution();
        return new Response(null, { status: 204 });
      }
      return new Response("Method not allowed", { status: 405 });
    } catch (cause) {
      if (cause instanceof z.ZodError) return new Response(z.prettifyError(cause), { status: 400 });
      console.error({
        event: "sandbox.request.failed",
        sandboxName,
        resource,
        error: describeError(cause),
      });
      return new Response("Sandbox request failed", { status: 500 });
    }
  },
} satisfies ExportedHandler<Env>;

function requireContainer(ctx: DurableObjectState): Container {
  const container = ctx.container;
  if (container === undefined) throw new Error("Container attachment is unavailable");
  return container;
}

// A body that is not JSON fails validation with 400, like any other bad body, instead of a 500.
async function parseBody<T>(request: Request, schema: z.ZodType<T>): Promise<T> {
  return schema.parse(await request.json().catch(() => undefined));
}

// Structured logs drop an Error's message and stack because they are not enumerable.
function describeError(cause: unknown): string {
  return cause instanceof Error && cause.stack !== undefined ? cause.stack : String(cause);
}

import { Files, SandboxFileError, SandboxProtocolError } from "@cloudflare/sandbox";
import { DurableObject } from "cloudflare:workers";

const SANDBOX_NAME_PATTERN = /^[a-z0-9][a-z0-9-]{0,62}$/;
const APP_DIRECTORY = "/workspace/app";
const SOURCE_PATH = `${APP_DIRECTORY}/src/main.js`;
const DEV_SERVER_LOG_PATH = "/tmp/dev-server.log";
const DEV_SERVER_PORT = 5173;
const DEV_SERVER_START_TIMEOUT_MS = 60_000;
const INACTIVITY_TIMEOUT_MS = 10 * 60 * 1_000;

// Replace this loop with the native getTcpPort() readiness option when it ships.
const NOT_LISTENING_PREFIXES = [
  "The container is not listening in the TCP address ",
  "Container is not listening to port ",
];

interface Env {
  SANDBOX: DurableObjectNamespace<PreviewSandbox>;
  PREVIEW_DOMAIN: string;
}

type PreviewResult =
  | { status: "ready"; url: string }
  | { status: "exited"; exitCode: number; log: string }
  | { status: "timed-out"; log: string };

export class PreviewSandbox extends DurableObject<Env> {
  readonly #container: Container;
  readonly #files: Files;
  #starting: Promise<PreviewResult> | undefined;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    this.#container = requireContainer(ctx);
    this.#files = new Files(this.#container);
    // Each Durable Object instance must set its own timeout; it is not inherited.
    if (this.#container.running) {
      void ctx.blockConcurrencyWhile(() =>
        this.#container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS),
      );
    }
  }

  async writeSource(source: ReadableStream<Uint8Array>, sandboxName: string): Promise<void> {
    await this.#ensureExecution(sandboxName);
    await this.#files.writeFile(SOURCE_PATH, source);
  }

  startPreview(sandboxName: string): Promise<PreviewResult> {
    if (this.#starting !== undefined) return this.#starting;
    const starting = this.#startPreview(sandboxName).finally(() => {
      if (this.#starting === starting) this.#starting = undefined;
    });
    this.#starting = starting;
    return starting;
  }

  async resetExecution(): Promise<void> {
    // A start in flight belongs to the Container being destroyed.
    this.#starting = undefined;
    if (this.#container.running) await this.#container.destroy();
  }

  // Preview requests never start the Container or the dev server.
  override async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    url.protocol = "http:";
    try {
      return await this.#container.getTcpPort(DEV_SERVER_PORT).fetch(new Request(url, request));
    } catch (cause) {
      if (!isNotListening(cause)) {
        console.error({ event: "preview.forward.failed", error: describeError(cause) });
      }
      return new Response("Preview is not running", { status: 503 });
    }
  }

  async #ensureExecution(sandboxName: string): Promise<void> {
    if (this.#container.running) return;
    this.#container.start({
      image: this.#container.images.sandbox,
      instance: "standard-1",
      enableInternet: false,
      labels: { example: "preview-workspace", sandbox: sandboxName },
    });
    await this.#container.setInactivityTimeout(INACTIVITY_TIMEOUT_MS);
  }

  async #startPreview(sandboxName: string): Promise<PreviewResult> {
    await this.#ensureExecution(sandboxName);
    const previewHost = `${sandboxName}.${this.env.PREVIEW_DOMAIN}`;
    const ready: PreviewResult = { status: "ready", url: `https://${previewHost}/` };
    if (await this.#devServerAnswers()) return ready;

    // Piped output would kill the server after this request ends, so write a log file.
    const server = await this.#container.exec(
      ["/bin/sh", "-c", `exec ./node_modules/.bin/vite >${DEV_SERVER_LOG_PATH} 2>&1`],
      {
        cwd: APP_DIRECTORY,
        env: { PREVIEW_HOST: previewHost },
        stdout: "ignore",
        stderr: "ignore",
      },
    );
    const exited = new AbortController();
    let exitCode: number | undefined;
    server.exitCode.then(
      (code) => {
        exitCode = code;
        exited.abort();
      },
      (cause: unknown) => exited.abort(cause),
    );
    const signal = AbortSignal.any([
      exited.signal,
      AbortSignal.timeout(DEV_SERVER_START_TIMEOUT_MS),
    ]);

    while (!signal.aborted) {
      try {
        if (await this.#devServerAnswers(signal)) return ready;
        await scheduler.wait(100, { signal });
      } catch (cause) {
        if (!signal.aborted) throw cause;
      }
    }
    if (exitCode !== undefined) {
      return { status: "exited", exitCode, log: await this.#devServerLog() };
    }
    if (exited.signal.aborted) throw exited.signal.reason;
    server.kill();
    return { status: "timed-out", log: await this.#devServerLog() };
  }

  async #devServerAnswers(signal?: AbortSignal): Promise<boolean> {
    try {
      const response = await this.#container
        .getTcpPort(DEV_SERVER_PORT)
        .fetch("http://localhost/", { signal });
      await response.body?.cancel();
      return true;
    } catch (cause) {
      if (isNotListening(cause)) return false;
      throw cause;
    }
  }

  async #devServerLog(): Promise<string> {
    return (await this.#files.readFile(DEV_SERVER_LOG_PATH)).text();
  }
}

export default {
  async fetch(request, env): Promise<Response> {
    const url = new URL(request.url);
    const previewSuffix = `.${env.PREVIEW_DOMAIN}`;
    if (url.hostname.endsWith(previewSuffix)) {
      const sandboxName = url.hostname.slice(0, -previewSuffix.length);
      if (!SANDBOX_NAME_PATTERN.test(sandboxName))
        return new Response("Not found", { status: 404 });
      return env.SANDBOX.getByName(sandboxName).fetch(request);
    }

    const match = /^\/sandboxes\/([^/]+)\/(source|preview|execution)$/.exec(url.pathname);
    if (match === null) return new Response("Not found", { status: 404 });

    const sandboxName = match[1];
    const resource = match[2];
    if (!SANDBOX_NAME_PATTERN.test(sandboxName)) {
      return new Response(
        "sandbox name must contain 1-63 lowercase letters, digits, or hyphens and start with a letter or digit",
        { status: 400 },
      );
    }

    const sandbox = env.SANDBOX.getByName(sandboxName);
    try {
      if (resource === "source" && request.method === "PUT") {
        if (request.body === null) {
          return new Response("Request body is required", { status: 400 });
        }
        await sandbox.writeSource(request.body, sandboxName);
        return new Response(null, { status: 204 });
      }
      if (resource === "preview" && request.method === "POST") {
        const result = await sandbox.startPreview(sandboxName);
        return Response.json(result, { status: result.status === "ready" ? 200 : 502 });
      }
      if (resource === "execution" && request.method === "DELETE") {
        await sandbox.resetExecution();
        return new Response(null, { status: 204 });
      }
      return new Response("Method not allowed", { status: 405 });
    } catch (cause) {
      console.error({
        event: "sandbox.request.failed",
        sandboxName,
        resource,
        error: describeError(cause),
      });
      return errorResponse(cause);
    }
  },
} satisfies ExportedHandler<Env>;

// Structured logs drop an Error's message and stack because they are not enumerable.
function describeError(cause: unknown): string {
  return cause instanceof Error && cause.stack !== undefined ? cause.stack : String(cause);
}

function isNotListening(cause: unknown): boolean {
  return (
    cause instanceof Error &&
    NOT_LISTENING_PREFIXES.some((prefix) => cause.message.startsWith(prefix))
  );
}

function requireContainer(ctx: DurableObjectState): Container {
  const container = ctx.container;
  if (container === undefined) throw new Error("Container attachment is unavailable");
  return container;
}

function errorResponse(cause: unknown): Response {
  if (SandboxFileError.is(cause)) {
    if (cause.code === "ENOENT") return new Response("Workspace file not found", { status: 404 });
    return new Response("Workspace file operation failed", { status: 500 });
  }
  if (SandboxProtocolError.is(cause)) {
    return new Response("Sandbox file protocol failed", { status: 500 });
  }
  return new Response("Sandbox request failed", { status: 500 });
}

